B06.befehl:
-- Gewöhnliche Tabelle: SQLite nimmt, was kommt
CREATE TABLE messung (wert INTEGER, gemessen DATE);
INSERT INTO messung VALUES ('abc', '2026-09-11');   -- gelingt
SELECT wert, typeof(wert), typeof(gemessen) FROM messung;
-- abc | text | text

-- STRICT (seit 3.37): nur INT, INTEGER, REAL, TEXT, BLOB, ANY – und Prüfung
CREATE TABLE messung_s (wert INTEGER, gemessen TEXT) STRICT;
INSERT INTO messung_s VALUES ('abc', '2026-09-11');
-- Error: cannot store TEXT value in INTEGER column messung_s.wert
INSERT INTO messung_s VALUES ('42', '2026-09-11');  -- gelingt: '42' wird 42

B08.befehl:
-- Eine Rohtabelle: ein JSON-Dokument je Zeile, wie eine Zeile aus fahrten.jsonl
CREATE TABLE fahrt_roh (doc TEXT);
INSERT INTO fahrt_roh VALUES
  ('{"fahrt_id":1,"rad_id":"R-057","start":{"station_id":6,"zeit":"2025-10-05T07:58:00"},"ziel":{"station_id":3},"dauer_min":7,"preis_eur":1.2}');

-- Spalten daraus machen
SELECT doc ->> '$.fahrt_id'          AS fahrt_id,       -- 1        (integer)
       doc ->  '$.rad_id'            AS rad_json,       -- "R-057"  (JSON-Text, mit Anführungszeichen)
       doc ->> '$.rad_id'            AS rad_id,         -- R-057    (SQL-Text)
       doc ->> '$.start.station_id'  AS start_station,  -- 6
       json_extract(doc, '$.start.zeit') AS start_zeit  -- 2025-10-05T07:58:00
FROM fahrt_roh;

-- Ein Array wird zur Tabelle
SELECT value FROM json_each('["R-001", "R-002", "R-003"]');

-- Und zurück: Zeilen zu JSON
SELECT bezirk, json_group_array(name) AS stationen FROM station GROUP BY bezirk;

